static inline int __builtin_cpu_supports(const char *feature)
{
    int cpuInfo[4] = {0};
    __cpuid(cpuInfo, 0);
    int max_leaf = cpuInfo[0];

    if (strcmp(feature, "ssse3") == 0) {
        if (max_leaf >= 1) {
